@Test
public void checkModulo() {
    int div = 7;
    for (int i = 20; i-- > 0; ) {
        long[] out = hashToLongs(i, 9001);
        int mod = modulo(out[0], out[1], div);
        Assert.assertTrue((mod < div) && (mod >= 0));
        mod = modulo(out, div);
        Assert.assertTrue((mod < div) && (mod >= 0));
    }
}

