@Test
public void testGetBucketIterator() throws Exception {
    BucketIterator biter = fields.getBucketIterator();
    int count = 0;
    while (biter.next()) {
        Assert.assertEquals(biter.getKey(), HashUtils.keyOfPair(vals[count]));
        Assert.assertEquals(biter.getValue(), HashUtils.valOfPair(vals[count]));
        ++count;
    }
    Assert.assertEquals(count, vals.length);
}

@Test
public void testFromFields() throws Exception {
    OnHeapHashFields hashFields = new OnHeapHashFields(preamble);
    for (int val : vals) {
        hashFields.updateBucket(HashUtils.keyOfPair(val), HashUtils.valOfPair(val), new NoopUpdateCallback());
    }
    // We ensure that the values in the hashFields are not sorted because one of the
    // things this should test is that the static method is sorting correctly.
    boolean sorted = true;
    int prevKey = -1;
    BucketIterator biter = hashFields.getBucketIterator();
    while (biter.next()) {
        if (prevKey > biter.getKey()) {
            sorted = false;
            break;
        }
        prevKey = biter.getKey();
    }
    Assert.assertFalse(sorted, "vals was changed!  Please adjust so that it doesn't result in sorted ordering.");
    fields = OnHeapImmutableCompactFields.fromFields(hashFields);
    testGetPreamble();
    testToCompact();
    testIntoByteArray();
    testNumBytesToSerialize();
    testGetBucketIterator();
}

@Test
public void testSerDe() {
    Preamble preamble = new Preamble.Builder().setLogConfigK((byte) 10).setSeed(Util.DEFAULT_UPDATE_SEED).setFlags((byte) 12).build();
    byte[] bytes = new byte[10];
    int initOffset = 1;
    int newOffset = preamble.intoByteArray(bytes, initOffset);
    Assert.assertEquals(newOffset, initOffset + (Preamble.PREAMBLE_LONGS << 3));
    Memory mem = new MemoryRegion(new NativeMemory(bytes), 1, bytes.length - 1);
    Preamble serdePreamble = Preamble.fromMemory(mem);
    Assert.assertEquals(serdePreamble, preamble);
}

@Test
public void testMaxAuxSize() {
    Preamble preamble10 = new Preamble.Builder().setLogConfigK((byte) 10).build();
    final int intByteSize = 4;
    Assert.assertEquals(preamble10.getMaxAuxSize(), 16 * intByteSize);
    Preamble preamble13 = new Preamble.Builder().setLogConfigK((byte) 13).build();
    Assert.assertEquals(preamble13.getMaxAuxSize(), 32 * intByteSize);
    Preamble preamble16 = new Preamble.Builder().setLogConfigK((byte) 16).build();
    Assert.assertEquals(preamble16.getMaxAuxSize(), 256 * intByteSize);
    Preamble preamble26 = new Preamble.Builder().setLogConfigK((byte) 21).build();
    Assert.assertEquals(preamble26.getMaxAuxSize(), 8192 * intByteSize);
}

